//! An illustrative, host-supplied gather / act / verify timeline; it never calls tools.
use crate::{
    foundation::{Theme, ThemeMode},
    primitives::{
        family::{Paint, Tone, disabled_motion, face},
        glyph::{Glyph, icon, spinner},
        kense_mark,
        nav::tr,
    },
};
use gpui::{prelude::*, *};
use std::{
    f32::consts::{FRAC_PI_2, PI, TAU},
    sync::{Arc, OnceLock},
};
use web_time::Instant;

#[derive(Clone)]
pub struct LoopCall {
    pub tool: SharedString,
    pub action: SharedString,
    pub result: SharedString,
    pub failed: bool,
}
impl LoopCall {
    pub fn new(
        tool: impl Into<SharedString>,
        action: impl Into<SharedString>,
        result: impl Into<SharedString>,
    ) -> Self {
        Self {
            tool: tool.into(),
            action: action.into(),
            result: result.into(),
            failed: false,
        }
    }
}
#[derive(Clone)]
pub struct LoopIteration {
    pub context: SharedString,
    pub detail: SharedString,
    pub tokens: u64,
    pub calls: Vec<LoopCall>,
    pub passed: bool,
    pub verification: SharedString,
}
impl LoopIteration {
    pub fn new(
        context: impl Into<SharedString>,
        tokens: u64,
        passed: bool,
        verification: impl Into<SharedString>,
    ) -> Self {
        Self {
            context: context.into(),
            detail: "".into(),
            tokens,
            calls: Vec::new(),
            passed,
            verification: verification.into(),
        }
    }
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LoopStation {
    Gather,
    Act,
    Verify,
}
#[derive(Clone, Debug, PartialEq)]
pub enum AgentLoopEvent {
    Station {
        iteration: usize,
        station: LoopStation,
    },
    Done {
        passed: bool,
    },
    Speed(f32),
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Cue {
    Gather,
    Call(usize),
    ResolveCall(usize),
    Verify,
    ResolveCheck,
    Finish,
}
#[derive(Clone, Copy)]
struct Beat {
    iteration: usize,
    cue: Cue,
}
impl Beat {
    fn station(self) -> LoopStation {
        match self.cue {
            Cue::Gather | Cue::Finish => LoopStation::Gather,
            Cue::Call(_) | Cue::ResolveCall(_) => LoopStation::Act,
            Cue::Verify | Cue::ResolveCheck => LoopStation::Verify,
        }
    }
    fn duration(self) -> f32 {
        match self.cue {
            Cue::Gather => 0.95,
            Cue::Call(_) => 0.72,
            Cue::ResolveCall(_) => 1.00,
            Cue::Verify => 0.72,
            Cue::ResolveCheck => 1.12,
            Cue::Finish => 0.76,
        }
    }
    fn step_stop(self) -> bool {
        matches!(
            self.cue,
            Cue::Gather | Cue::ResolveCall(_) | Cue::ResolveCheck | Cue::Finish
        )
    }
}
fn timeline(iterations: &[LoopIteration]) -> Vec<Beat> {
    let mut beats = Vec::new();
    for (iteration, item) in iterations.iter().enumerate() {
        let mut push = |cue| beats.push(Beat { iteration, cue });
        push(Cue::Gather);
        for call in 0..item.calls.len() {
            push(Cue::Call(call));
            push(Cue::ResolveCall(call));
        }
        push(Cue::Verify);
        push(Cue::ResolveCheck);
    }
    if let Some(iteration) = iterations.len().checked_sub(1) {
        beats.push(Beat {
            iteration,
            cue: Cue::Finish,
        });
    }
    beats
}

fn ease(t: f32) -> f32 {
    let t = t.clamp(0., 1.);
    t * t * (3. - 2. * t)
}

fn station_angle(station: LoopStation) -> f32 {
    match station {
        LoopStation::Gather => -FRAC_PI_2,
        LoopStation::Act => PI / 6.,
        LoopStation::Verify => 5. * PI / 6.,
    }
}

#[derive(Default)]
struct Lanes {
    check: Option<(usize, Beat)>,
    tool: Option<(usize, Beat)>,
    gathered: usize,
}
fn landed_lanes(beats: &[Beat]) -> Lanes {
    let mut lanes = Lanes::default();
    for (index, beat) in beats.iter().copied().enumerate() {
        match beat.cue {
            Cue::Gather => lanes.gathered = beat.iteration + 1,
            Cue::Call(_) | Cue::ResolveCall(_) => lanes.tool = Some((index, beat)),
            Cue::Verify | Cue::ResolveCheck => lanes.check = Some((index, beat)),
            Cue::Finish => {}
        }
    }
    lanes
}

pub struct AgentLoop {
    title: SharedString,
    task: SharedString,
    summary: SharedString,
    model: SharedString,
    iterations: Vec<LoopIteration>,
    beats: Vec<Beat>,
    landed: usize,
    elapsed: f32,
    playing: bool,
    autoplay: bool,
    step_to: Option<usize>,
    speed: f32,
    last_frame: Option<Instant>,
    in_view: bool,
    visibility: fn() -> bool,
    measured_width: Option<f32>,
    next_focus: Option<FocusHandle>,
    restart_focus: Option<FocusHandle>,
}
impl EventEmitter<AgentLoopEvent> for AgentLoop {}
impl AgentLoop {
    pub fn new(task: impl Into<SharedString>, iterations: Vec<LoopIteration>) -> Self {
        let beats = timeline(&iterations);
        Self {
            title: "Agent loop".into(),
            task: task.into(),
            summary: "".into(),
            model: "Kense".into(),
            iterations,
            beats,
            landed: 0,
            elapsed: 0.,
            playing: false,
            autoplay: false,
            step_to: None,
            speed: 1.,
            last_frame: None,
            in_view: true,
            visibility: || true,
            measured_width: None,
            next_focus: None,
            restart_focus: None,
        }
    }
    pub fn title(mut self, title: impl Into<SharedString>) -> Self {
        self.title = title.into();
        self
    }
    pub fn summary(mut self, summary: impl Into<SharedString>) -> Self {
        self.summary = summary.into();
        self
    }
    pub fn model(mut self, model: impl Into<SharedString>) -> Self {
        self.model = model.into();
        self
    }
    /// Starts the first run once visible. With reduced motion, shows its result instead.
    pub fn autoplay(mut self, enabled: bool) -> Self {
        self.autoplay = enabled;
        self
    }
    /// Lets an embedding host report whether the preview is visible.
    pub fn visibility(mut self, visible: fn() -> bool) -> Self {
        self.visibility = visible;
        self
    }
    pub fn set_playing(&mut self, playing: bool, cx: &mut Context<Self>) {
        self.autoplay = false;
        self.playing = playing && !self.finished() && !self.beats.is_empty();
        self.step_to = None;
        self.last_frame = None;
        cx.notify();
    }
    pub fn restart(&mut self, cx: &mut Context<Self>) {
        self.landed = 0;
        self.elapsed = 0.;
        self.set_playing(false, cx);
    }
    pub fn set_speed(&mut self, speed: f32, cx: &mut Context<Self>) {
        self.speed = if speed.is_finite() {
            speed.clamp(0., 2.)
        } else {
            1.
        };
        self.last_frame = None;
        cx.emit(AgentLoopEvent::Speed(self.speed));
        cx.notify();
    }
    pub fn step(&mut self, cx: &mut Context<Self>) {
        let Some(stop) = self
            .beats
            .iter()
            .enumerate()
            .skip(self.landed)
            .find_map(|(index, beat)| beat.step_stop().then_some(index + 1))
        else {
            return;
        };
        self.set_playing(true, cx);
        self.step_to = Some(stop);
        if disabled_motion(cx) {
            while self.landed < stop {
                self.advance(cx);
            }
        }
    }
    fn finished(&self) -> bool {
        !self.beats.is_empty() && self.landed >= self.beats.len()
    }
    fn advance(&mut self, cx: &mut Context<Self>) {
        let Some(beat) = self.beats.get(self.landed).copied() else {
            return;
        };
        self.landed += 1;
        self.elapsed = 0.;
        match beat.cue {
            Cue::Gather | Cue::Call(_) | Cue::Verify => cx.emit(AgentLoopEvent::Station {
                iteration: beat.iteration,
                station: beat.station(),
            }),
            Cue::Finish => cx.emit(AgentLoopEvent::Done {
                passed: self.iterations[beat.iteration].passed,
            }),
            _ => {}
        }
        if self.finished() || self.step_to == Some(self.landed) {
            self.playing = false;
            self.step_to = None;
            self.last_frame = None;
        }
    }
    fn tick(&mut self, visible: bool, reduce: bool, w: &Window, cx: &mut Context<Self>) {
        if !visible {
            self.last_frame = None;
            return;
        }
        if std::mem::take(&mut self.autoplay) && !self.beats.is_empty() {
            if reduce {
                self.landed = self.beats.len();
            } else {
                self.playing = true;
            }
        }
        let rate = if self.step_to.is_some() && self.speed == 0. {
            1.
        } else {
            self.speed
        };
        if !self.playing || rate == 0. {
            self.last_frame = None;
            return;
        }
        let now = Instant::now();
        let dt = self.last_frame.replace(now).map_or(0., |last| {
            now.saturating_duration_since(last).as_secs_f32().min(0.1)
        });
        if let Some(next) = self.beats.get(self.landed) {
            self.elapsed += dt * rate;
            if self.elapsed >= next.duration() {
                self.advance(cx);
            }
        }
        if self.playing {
            w.request_animation_frame();
        }
    }
}

struct LoopLayout {
    ring_width: f32,
    radius: f32,
    center_y: f32,
    ring_height: f32,
    horizontal: bool,
    split: bool,
    compact: bool,
}
impl LoopLayout {
    fn new(width: f32) -> Self {
        let horizontal = width >= 604.;
        let ring_width = if horizontal { width - 220. } else { width };
        let compact = ring_width < 355.;
        let radius = if compact {
            (ring_width * 0.22).clamp(40., 76.)
        } else {
            94.
        };
        let center_y = 34. + radius;
        Self {
            ring_width,
            radius,
            center_y,
            ring_height: if compact {
                center_y + radius + 17.
            } else {
                242.
            },
            horizontal,
            split: horizontal || ring_width >= 440.,
            compact,
        }
    }
    fn station_x(&self, angle: f32) -> f32 {
        self.ring_width * 0.5 + self.radius * angle.cos()
    }
}

fn point_on_ring(center: Point<Pixels>, radius: f32, angle: f32) -> Point<Pixels> {
    center + point(px(radius * angle.cos()), px(radius * angle.sin()))
}
fn stroke_arc(
    w: &mut Window,
    center: Point<Pixels>,
    radius: f32,
    angles: (f32, f32),
    width: f32,
    ink: Hsla,
) {
    let (from, to) = angles;
    if to <= from {
        return;
    }
    let segments = ((to - from).abs() * 18.).ceil().max(1.) as usize;
    let mut path = PathBuilder::stroke(px(width));
    path.move_to(point_on_ring(center, radius, from));
    for i in 1..=segments {
        path.line_to(point_on_ring(
            center,
            radius,
            from + (to - from) * i as f32 / segments as f32,
        ));
    }
    if let Ok(path) = path.build() {
        w.paint_path(path, ink);
    }
}

fn dot(w: &mut Window, center: Point<Pixels>, diameter: f32, color: Hsla) {
    w.paint_quad(
        fill(
            Bounds::centered_at(center, size(px(diameter), px(diameter))),
            color,
        )
        .corner_radii(px(diameter / 2.)),
    );
}

fn model_mark(mode: ThemeMode) -> Arc<Image> {
    static LIGHT: OnceLock<Arc<Image>> = OnceLock::new();
    static DARK: OnceLock<Arc<Image>> = OnceLock::new();
    let (cache, bytes) = match mode {
        ThemeMode::Light => (&LIGHT, kense_mark::LIGHT),
        ThemeMode::Dark => (&DARK, kense_mark::DARK),
    };
    cache
        .get_or_init(|| Arc::new(Image::from_bytes(ImageFormat::Png, bytes.to_vec())))
        .clone()
}

fn tokens(value: u64) -> String {
    if value >= 1_000 {
        let whole = value / 1000;
        let decimal = value % 1000 / 100;
        if decimal == 0 {
            format!("{whole}K")
        } else {
            format!("{whole}.{decimal}K")
        }
    } else {
        value.to_string()
    }
}

impl AgentLoop {
    fn ring(
        &self,
        layout: &LoopLayout,
        lanes: &Lanes,
        p: Paint,
        blue: Hsla,
        reduce: bool,
        cx: &App,
    ) -> Div {
        let last = self.landed.checked_sub(1).map(|index| self.beats[index]);
        let next = self.beats.get(self.landed).copied();
        let station = last.map_or(LoopStation::Gather, Beat::station);
        let from = station_angle(station);
        let target = next.map_or(station, Beat::station);
        let progress = next.map_or(0., |beat| self.elapsed / beat.duration());
        let travel = if reduce { 0. } else { ease(progress / 0.88) };
        let finishing = next.is_some_and(|beat| beat.cue == Cue::Finish);
        let angle = if finishing {
            from
        } else {
            from + (station_angle(target) - from).rem_euclid(TAU) * travel
        };
        let trail = if self.playing && !finishing && target != station && !reduce {
            (PI * travel).sin() * 0.85
        } else {
            0.
        };
        let done = self.finished();
        let active = (self.landed > 0 || self.elapsed > 0.) && !done && !finishing;
        let complete = if done {
            1.
        } else if finishing && !reduce {
            ease(progress)
        } else {
            0.
        };
        let passed = self.iterations.last().is_some_and(|item| item.passed);
        let completion_ink = if passed { blue } else { p.danger };
        let (radius, center_y, ring_height, split) = (
            layout.radius,
            layout.center_y,
            layout.ring_height,
            layout.split,
        );
        let pin = |lane: Option<(usize, Beat)>| {
            lane.map(|(index, beat)| {
                let appearing =
                    index + 1 == self.landed && matches!(beat.cue, Cue::Call(_) | Cue::Verify);
                if reduce || !appearing {
                    1.
                } else {
                    ease(self.elapsed / 0.19)
                }
            })
        };
        let (check_pin, tool_pin) = if split || lanes.check.zip(lanes.tool).is_none() {
            (pin(lanes.check), pin(lanes.tool))
        } else if lanes.check.map(|(index, _)| index) > lanes.tool.map(|(index, _)| index) {
            (pin(lanes.check), None)
        } else {
            (None, pin(lanes.tool))
        };
        let orbit = canvas(
            |_, _, _| (),
            move |b, _, w, _| {
                let center = point(b.center().x, b.top() + px(center_y));
                stroke_arc(w, center, radius, (0., TAU), 1.5, p.line);
                stroke_arc(
                    w,
                    center,
                    radius,
                    (-FRAC_PI_2, -FRAC_PI_2 + complete * TAU),
                    1.75,
                    completion_ink,
                );
                for (which, growth) in [
                    (LoopStation::Verify, check_pin),
                    (LoopStation::Act, tool_pin),
                ] {
                    if !split && growth.is_none() {
                        continue;
                    }
                    let pos = point_on_ring(center, radius, station_angle(which));
                    let length = (b.top() + px(ring_height) - pos.y - px(6.)).max(px(0.));
                    w.paint_quad(fill(
                        Bounds::new(pos + point(px(-0.5), px(5.)), size(px(1.), length + px(1.))),
                        p.line,
                    ));
                    if let Some(growth) = growth {
                        w.paint_quad(fill(
                            Bounds::new(
                                pos + point(px(-0.5), px(5.)),
                                size(px(1.), (length + px(1.)) * growth),
                            ),
                            blue.opacity(0.45),
                        ));
                    }
                }
                for a in [-PI / 6., FRAC_PI_2, 7. * PI / 6.] {
                    let pos = point_on_ring(center, radius, a);
                    let radial = point(px(a.cos()), px(a.sin()));
                    let tangent = point(-radial.y, radial.x);
                    let tip = pos + tangent * 3.;
                    let back = pos - tangent * 3.;
                    let mut arrow = PathBuilder::stroke(px(1.35));
                    arrow.move_to(back + radial * 3.);
                    arrow.line_to(tip);
                    arrow.line_to(back - radial * 3.);
                    if let Ok(path) = arrow.build() {
                        w.paint_path(path, if done { completion_ink } else { p.faint });
                    }
                }
                for which in [LoopStation::Gather, LoopStation::Act, LoopStation::Verify] {
                    let pos = point_on_ring(center, radius, station_angle(which));
                    dot(w, pos, 11., if done { completion_ink } else { p.faint });
                    dot(w, pos, 8., p.panel);
                }
                if active {
                    for n in (0..14).rev() {
                        if trail <= 0. {
                            break;
                        }
                        let a = angle - trail * (n + 1) as f32 / 14.;
                        let b = angle - trail * n as f32 / 14.;
                        stroke_arc(
                            w,
                            center,
                            radius,
                            (a, b + 0.004),
                            2.6,
                            blue.opacity(0.77 * (1. - n as f32 / 14.)),
                        );
                    }
                    let pos = point_on_ring(center, radius, angle);
                    dot(
                        w,
                        pos,
                        19.,
                        blue.opacity(if trail == 0. { 0.18 } else { 0.10 }),
                    );
                    dot(w, pos, 10., blue);
                }
            },
        )
        .size_full();
        let labels_below = layout.ring_width < 236.;
        let station_label = |station, glyph, text: &'static str| {
            let ink = p.secondary;
            let left = station == LoopStation::Verify;
            let centered = station == LoopStation::Gather || labels_below;
            let show_icon = !layout.compact || station == LoopStation::Gather;
            div()
                .w_full()
                .flex()
                .items_center()
                .when(centered, |v| v.justify_center())
                .when(!centered && left, |v| v.justify_end())
                .min_w_0()
                .gap_1()
                .text_size(px(if layout.compact { 12. } else { 13. }))
                .line_height(px(16.))
                .text_color(ink)
                .when(show_icon && !left, |v| v.child(icon(glyph, 13., ink)))
                .child(div().min_w_0().truncate().child(text))
                .when(show_icon && left, |v| v.child(icon(glyph, 13., ink)))
        };
        let lower_y = center_y + radius * 0.5;
        let verify_x = layout.station_x(station_angle(LoopStation::Verify));
        let act_x = layout.station_x(station_angle(LoopStation::Act));
        let center_status = if done {
            format!("{} {}", tr(cx, "Loops:", "轮次："), self.iterations.len())
        } else if let Some(beat) = last {
            format!("{} {}", tr(cx, "Loop", "轮次"), beat.iteration + 1)
        } else {
            tr(cx, "Ready", "准备就绪").to_owned()
        };
        div()
            .relative()
            .w_full()
            .h(px(ring_height))
            .flex_none()
            .child(orbit)
            .child(
                div()
                    .absolute()
                    .top_0()
                    .left_0()
                    .right_0()
                    .child(station_label(
                        LoopStation::Gather,
                        Glyph::Folder,
                        tr(cx, "Gather context", "收集上下文"),
                    )),
            )
            .child(
                div()
                    .absolute()
                    .top(px(if labels_below {
                        lower_y + 12.
                    } else {
                        lower_y - 8.
                    }))
                    .left(px(0.))
                    .w(px(if labels_below {
                        verify_x + 27.
                    } else {
                        (verify_x - 10.).max(0.)
                    }))
                    .child(station_label(
                        LoopStation::Verify,
                        Glyph::Check,
                        tr(cx, "Verify", "验证"),
                    )),
            )
            .child(
                div()
                    .absolute()
                    .top(px(if labels_below {
                        lower_y + 12.
                    } else {
                        lower_y - 8.
                    }))
                    .right(px(0.))
                    .w(px(if labels_below {
                        layout.ring_width - act_x + 27.
                    } else {
                        (layout.ring_width - act_x - 10.).max(0.)
                    }))
                    .child(station_label(
                        LoopStation::Act,
                        Glyph::Settings,
                        tr(cx, "Take action", "执行操作"),
                    )),
            )
            .child(
                div()
                    .absolute()
                    .top(px(center_y - 37.))
                    .left_0()
                    .right_0()
                    .flex()
                    .flex_col()
                    .items_center()
                    .gap_1()
                    .child(if self.model.as_ref() == "Kense" {
                        img(model_mark(Theme::global(cx).mode))
                            .size(px(22.))
                            .into_any_element()
                    } else {
                        icon(Glyph::Curious, 22., blue).into_any_element()
                    })
                    .child(
                        div()
                            .max_w(px(radius * 1.48))
                            .truncate()
                            .font_weight(FontWeight::MEDIUM)
                            .child(self.model.clone()),
                    )
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap_1()
                            .text_size(px(12.))
                            .text_color(p.secondary)
                            .when(done, |v| {
                                v.child(icon(
                                    if passed { Glyph::Check } else { Glyph::Alert },
                                    12.,
                                    if passed { p.success } else { p.danger },
                                ))
                            })
                            .child(center_status),
                    ),
            )
    }

    fn result(
        &self,
        lane: Option<(usize, Beat)>,
        empty: &'static str,
        p: Paint,
        radius: Pixels,
        reduce: bool,
        cx: &App,
    ) -> Div {
        let panel = div()
            .w_full()
            .h(px(56.))
            .min_w_0()
            .flex()
            .items_center()
            .gap_2()
            .overflow_hidden()
            .px_3()
            .rounded(radius)
            .border_1()
            .border_color(p.line)
            .text_size(px(12.))
            .line_height(px(17.));
        let Some((index, beat)) = lane else {
            return panel
                .border_dashed()
                .justify_center()
                .text_center()
                .text_color(p.faint)
                .child(div().min_w_0().truncate().child(empty));
        };
        let item = &self.iterations[beat.iteration];
        let pending = matches!(beat.cue, Cue::Call(_) | Cue::Verify);
        let (glyph, title, detail, failed) = match beat.cue {
            Cue::Call(call) | Cue::ResolveCall(call) => {
                let call = &item.calls[call];
                (
                    Glyph::Settings,
                    format!("{} · {}", call.tool, call.action),
                    if pending {
                        tr(cx, "Running tool…", "正在运行工具…").into()
                    } else {
                        call.result.clone()
                    },
                    call.failed,
                )
            }
            Cue::Verify | Cue::ResolveCheck => {
                let label = if pending {
                    tr(cx, "Checking", "正在验证")
                } else if item.passed {
                    tr(cx, "Check passed", "检查通过")
                } else {
                    tr(cx, "Needs another pass", "需要再次检查")
                };
                (
                    Glyph::Check,
                    label.to_owned(),
                    if pending {
                        tr(cx, "Reviewing the result…", "正在核对结果…").into()
                    } else {
                        item.verification.clone()
                    },
                    !item.passed,
                )
            }
            _ => unreachable!("result slots only contain tool and check beats"),
        };
        let entering = if reduce || index + 1 != self.landed || !pending {
            1.
        } else {
            ease(self.elapsed / 0.19)
        };
        panel.relative().child(
            div()
                .absolute()
                .left_0()
                .right_0()
                .top(px(6. * (1. - entering)))
                .h_full()
                .px_3()
                .flex()
                .items_center()
                .gap_2()
                .opacity(0.28 + entering * 0.72)
                .child(icon(glyph, 14., p.secondary))
                .child(
                    div()
                        .flex_1()
                        .min_w_0()
                        .child(
                            div()
                                .truncate()
                                .font_weight(FontWeight::MEDIUM)
                                .child(title),
                        )
                        .child(div().truncate().text_color(p.secondary).child(detail)),
                )
                .map(|v| {
                    if pending {
                        v.child(spinner(
                            if reduce { 0. } else { self.elapsed * 1.25 },
                            15.,
                            p.secondary,
                        ))
                    } else {
                        v.child(icon(
                            if failed { Glyph::Alert } else { Glyph::Check },
                            15.,
                            if failed { p.danger } else { p.success },
                        ))
                    }
                }),
        )
    }

    fn context_cards(
        &self,
        lanes: &Lanes,
        layout: &LoopLayout,
        p: Paint,
        r: Pixels,
        reduce: bool,
        cx: &App,
    ) -> Div {
        let total = self
            .iterations
            .iter()
            .take(lanes.gathered)
            .fold(0u64, |sum, it| sum.saturating_add(it.tokens));
        let count = if !reduce
            && self.playing
            && self.landed > 0
            && self.beats[self.landed - 1].cue == Cue::Gather
        {
            let recent = self.iterations[lanes.gathered - 1].tokens;
            total.saturating_sub(recent).saturating_add(
                (recent as f64 * f64::from(ease(self.elapsed / 0.24))).round() as u64,
            )
        } else {
            total
        };
        let mut section = div()
            .min_w_0()
            .flex()
            .flex_col()
            .gap_2()
            .when(layout.horizontal, |v| {
                v.w(px(204.))
                    .flex_none()
                    .pl_3()
                    .border_l_1()
                    .border_color(p.line)
            })
            .when(!layout.horizontal, |v| {
                v.w_full().pt_3().border_t_1().border_color(p.line)
            })
            .child(
                div()
                    .flex()
                    .items_center()
                    .justify_between()
                    .gap_2()
                    .text_size(px(12.))
                    .line_height(px(18.))
                    .text_color(p.secondary)
                    .child(
                        div()
                            .text_color(p.ink)
                            .font_weight(FontWeight::MEDIUM)
                            .child(tr(cx, "Context", "上下文")),
                    )
                    .child(format!("{} tokens", tokens(count))),
            );
        let columns = if layout.horizontal || layout.compact {
            1
        } else {
            2
        };
        for (row, chunk) in self.iterations.chunks(columns).enumerate() {
            let mut slots = div().w_full().flex().gap_2();
            for (col, item) in chunk.iter().enumerate() {
                let received = row * columns + col < lanes.gathered;
                let card = div()
                    .flex_1()
                    .min_w_0()
                    .h(px(56.))
                    .px_2()
                    .rounded(r)
                    .border_1()
                    .border_color(p.line)
                    .flex()
                    .items_center()
                    .gap_2()
                    .text_size(px(12.))
                    .line_height(px(16.));
                slots = slots.child(if received {
                    card.child(icon(Glyph::FileText, 14., p.secondary)).child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .child(
                                div()
                                    .flex()
                                    .items_center()
                                    .justify_between()
                                    .gap_1()
                                    .child(
                                        div()
                                            .min_w_0()
                                            .truncate()
                                            .font_weight(FontWeight::MEDIUM)
                                            .child(item.context.clone()),
                                    )
                                    .child(
                                        div()
                                            .flex_none()
                                            .text_color(p.secondary)
                                            .child(tokens(item.tokens)),
                                    ),
                            )
                            .child(
                                div()
                                    .truncate()
                                    .text_color(p.faint)
                                    .child(item.detail.clone()),
                            ),
                    )
                } else {
                    card.border_dashed().child(
                        div().w_full().text_center().text_color(p.faint).child(tr(
                            cx,
                            "Waiting for context",
                            "等待收集上下文",
                        )),
                    )
                });
            }
            if chunk.len() < columns {
                slots = slots.child(div().flex_1());
            }
            section = section.child(slots);
        }
        section
    }
}

impl Render for AgentLoop {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if self.next_focus.is_none() {
            self.next_focus = Some(cx.focus_handle().tab_stop(true));
            self.restart_focus = Some(cx.focus_handle().tab_stop(true));
        }
        let p = Paint::get(cx);
        let radius = crate::foundation::surface_radius(cx);
        let mode = Theme::global(cx).mode;
        let blue: Hsla = rgb(if mode == ThemeMode::Dark {
            0x72a5ff
        } else {
            0x3569d6
        })
        .into();
        let reduce = disabled_motion(cx);
        let viewport = w.viewport_size();
        let visible = self.in_view && (self.visibility)() && w.is_visible();
        self.tick(visible, reduce, w, cx);
        let done = self.finished();
        if done && self.next_focus.as_ref().is_some_and(|h| h.is_focused(w)) {
            let target = self.restart_focus.as_ref().unwrap().clone();
            cx.on_next_frame(w, move |_, w, cx| target.focus(w, cx));
        }
        let passed = self.iterations.last().is_some_and(|it| it.passed);
        let (status, status_glyph, status_color) = if done {
            if passed {
                (tr(cx, "Done", "已完成"), Glyph::Check, p.success)
            } else {
                (tr(cx, "Stopped", "已停止"), Glyph::Alert, p.danger)
            }
        } else if self.playing {
            (tr(cx, "Running", "运行中"), Glyph::Play, blue)
        } else if self.landed > 0 || self.elapsed > 0. {
            (tr(cx, "Paused", "已暂停"), Glyph::Pause, p.secondary)
        } else {
            (tr(cx, "Ready", "准备就绪"), Glyph::Clock, p.secondary)
        };
        let available = self
            .measured_width
            .unwrap_or_else(|| (f32::from(viewport.width) - 82.).min(710.));
        let layout = LoopLayout::new(available.max(100.));
        let lanes = landed_lanes(&self.beats[..self.landed]);
        let compact = f32::from(viewport.width) < 460.;
        let inset = if compact { 14. } else { 24. };
        let mut root = div()
            .id("agent-loop")
            .role(Role::Group)
            .aria_label(self.title.clone())
            .w_full()
            .max_w(px(760.))
            .rounded(radius)
            .border_1()
            .border_color(p.line)
            .bg(p.panel)
            .text_color(p.ink)
            .text_size(px(14.))
            .line_height(px(20.))
            .flex()
            .flex_col()
            .gap_4()
            .p(px(inset))
            .child(
                div()
                    .flex()
                    .items_center()
                    .justify_between()
                    .gap_2()
                    .child(
                        div()
                            .min_w_0()
                            .truncate()
                            .text_size(px(16.))
                            .font_weight(FontWeight::MEDIUM)
                            .child(self.title.clone()),
                    )
                    .child(
                        div()
                            .flex()
                            .flex_none()
                            .items_center()
                            .gap_1()
                            .text_color(status_color)
                            .child(icon(status_glyph, 13., status_color))
                            .child(status),
                    ),
            )
            .child(div().min_h(px(40.)).text_color(p.secondary).child(
                if done && !self.summary.is_empty() {
                    self.summary.clone()
                } else {
                    self.task.clone()
                },
            ));
        let mut results = div().w_full().flex().gap_2();
        if layout.split {
            results = results
                .child(div().flex_1().min_w_0().child(self.result(
                    lanes.check,
                    tr(cx, "Check results", "检查结果"),
                    p,
                    radius,
                    reduce,
                    cx,
                )))
                .child(div().flex_1().min_w_0().child(self.result(
                    lanes.tool,
                    tr(cx, "Tool results", "工具结果"),
                    p,
                    radius,
                    reduce,
                    cx,
                )));
        } else {
            let latest = [lanes.check, lanes.tool]
                .into_iter()
                .flatten()
                .max_by_key(|(index, _)| *index);
            results = results.child(self.result(
                latest,
                tr(cx, "Tool and check results", "工具与检查结果"),
                p,
                radius,
                reduce,
                cx,
            ));
        }
        let weak = cx.weak_entity();
        root = root.child(
            div()
                .on_children_prepainted(move |bounds, _, cx| {
                    let Some(b) = bounds.first() else { return };
                    let visible = b.left() < viewport.width
                        && b.top() < viewport.height
                        && b.right() > px(0.)
                        && b.bottom() > px(0.);
                    let width = f32::from(b.size.width);
                    let _ = weak.update(cx, |s, cx| {
                        if s.in_view != visible
                            || s.measured_width
                                .is_none_or(|previous| (previous - width).abs() >= 0.5)
                        {
                            if s.in_view != visible {
                                s.last_frame = None;
                            }
                            s.in_view = visible;
                            s.measured_width = Some(width);
                            cx.notify();
                        }
                    });
                })
                .child(
                    div()
                        .w_full()
                        .min_w_0()
                        .flex()
                        .gap_4()
                        .when(!layout.horizontal, |v| v.flex_col())
                        .child(
                            div()
                                .min_w_0()
                                .flex_1()
                                .flex()
                                .flex_col()
                                .child(self.ring(&layout, &lanes, p, blue, reduce, cx))
                                .child(results),
                        )
                        .child(self.context_cards(&lanes, &layout, p, radius, reduce, cx)),
                ),
        );
        if self.beats.is_empty() {
            return root;
        }
        let playing = self.playing;
        let play = if playing {
            tr(cx, "Pause", "暂停")
        } else if done {
            tr(cx, "Play again", "重播")
        } else {
            tr(cx, "Play", "播放")
        };
        let round_control = |id, label, glyph, enabled| {
            face(id, label, 36., 18., Tone::Surface, cx)
                .w(px(36.))
                .border_1()
                .border_color(p.line)
                .when(enabled, |v| {
                    v.hover(move |v| v.bg(p.hover))
                        .active(move |v| v.bg(p.line))
                })
                .when(!enabled, |v| v.opacity(0.38).cursor_default().tab_index(-1))
                .child(icon(glyph, 15., p.ink))
        };
        let mut speeds = div()
            .flex()
            .items_center()
            .gap_1()
            .p(px(3.))
            .rounded(radius)
            .bg(p.stage);
        for (i, speed) in [0.5_f32, 1., 2.].into_iter().enumerate() {
            let selected = (self.speed - speed).abs() < 0.01;
            speeds = speeds.child(
                face(
                    ("loop-speed", i),
                    format!("{speed}×"),
                    27.,
                    f32::from(radius) - 2.,
                    Tone::Clear,
                    cx,
                )
                .min_w(px(28.))
                .aria_selected(selected)
                .child(format!("{speed}×"))
                .px_1()
                .text_size(px(12.))
                .when(selected, |v| v.bg(p.panel).shadow_sm())
                .when(!selected, |v| {
                    v.text_color(p.secondary).hover(move |v| v.bg(p.hover))
                })
                .on_key_down(cx.listener(|s, e: &KeyDownEvent, _, cx| {
                    let speeds = [0.5_f32, 1., 2.];
                    let current = speeds
                        .iter()
                        .position(|v| (s.speed - v).abs() < 0.01)
                        .unwrap_or(1);
                    let target = match e.keystroke.key.as_str() {
                        "left" => current.saturating_sub(1),
                        "right" => (current + 1).min(2),
                        _ => return,
                    };
                    s.set_speed(speeds[target], cx);
                    cx.stop_propagation();
                }))
                .on_click(cx.listener(move |s, _, _, cx| s.set_speed(speed, cx))),
            );
        }
        root.child(
            div()
                .flex()
                .items_center()
                .justify_between()
                .flex_wrap()
                .gap_2()
                .pt_3()
                .border_t_1()
                .border_color(p.line)
                .child(
                    div()
                        .flex()
                        .items_center()
                        .gap_1()
                        .child(
                            round_control(
                                "loop-play",
                                play,
                                if playing { Glyph::Pause } else { Glyph::Play },
                                true,
                            )
                            .on_click(cx.listener(|s, _, _, cx| {
                                if s.finished() {
                                    s.restart(cx);
                                }
                                s.set_playing(!s.playing, cx);
                            })),
                        )
                        .child(
                            round_control(
                                "loop-step",
                                tr(cx, "Next step", "下一步"),
                                Glyph::Arrow,
                                !done,
                            )
                            .when(!done, |v| {
                                v.track_focus(self.next_focus.as_ref().unwrap())
                                    .on_click(cx.listener(|s, _, _, cx| s.step(cx)))
                            }),
                        )
                        .child(
                            round_control(
                                "loop-restart",
                                tr(cx, "Restart", "重新开始"),
                                Glyph::Undo,
                                true,
                            )
                            .track_focus(self.restart_focus.as_ref().unwrap())
                            .on_click(cx.listener(|s, _, _, cx| {
                                s.restart(cx);
                                s.set_playing(true, cx);
                            })),
                        ),
                )
                .child(
                    div()
                        .flex()
                        .items_center()
                        .gap_2()
                        .when(available >= 340., |v| {
                            v.child(
                                div()
                                    .text_size(px(12.))
                                    .text_color(p.secondary)
                                    .child(tr(cx, "Speed", "速度")),
                            )
                        })
                        .child(speeds),
                ),
        )
    }
}

#[cfg(test)]
mod tests {
    use super::{Beat, Cue, LoopCall, LoopIteration, landed_lanes, timeline};

    #[test]
    fn results_survive_later_stations_and_resolve_in_host_order() {
        let mut first = LoopIteration::new("logs", 3, false, "retry");
        first.calls.push(LoopCall::new("one", "read", "found"));
        first.calls.push(LoopCall::new("two", "inspect", "done"));
        let second = LoopIteration::new("fix", 4, true, "passed");
        let beats = timeline(&[first, second]);
        let sequence: Vec<_> = beats
            .iter()
            .filter(|beat| beat.step_stop())
            .map(|b| b.cue)
            .collect();
        assert_eq!(
            sequence,
            [
                Cue::Gather,
                Cue::ResolveCall(0),
                Cue::ResolveCall(1),
                Cue::ResolveCheck,
                Cue::Gather,
                Cue::ResolveCheck,
                Cue::Finish
            ]
        );
        let lanes = landed_lanes(&beats[..8]);
        assert_eq!(lanes.gathered, 2);
        assert!(matches!(
            lanes.tool,
            Some((
                _,
                Beat {
                    cue: Cue::ResolveCall(1),
                    ..
                }
            ))
        ));
        assert!(matches!(
            lanes.check,
            Some((
                _,
                Beat {
                    iteration: 0,
                    cue: Cue::ResolveCheck
                }
            ))
        ));
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    pub(crate) fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

//! Building blocks for collection navigation and contextual disclosures.
use crate::primitives::{
    control::UiLanguage,
    family::{Paint, Slide},
    flyout::TriggerBounds,
    glyph::{Glyph, icon},
};
use gpui::{prelude::*, *};
use std::time::Duration;
pub fn tr(cx: &App, en: &'static str, zh: &'static str) -> &'static str {
    UiLanguage::current(cx).text(en, zh)
}
pub fn column() -> Div {
    div().flex().flex_col().min_w_0()
}
pub fn row() -> Div {
    div().flex().items_center().min_w_0()
}
pub fn panel(cx: &App) -> Div {
    let p = Paint::get(cx);
    column()
        .bg(p.panel)
        .text_color(p.ink)
        .border_1()
        .border_color(p.line)
        .rounded(crate::foundation::surface_radius(cx))
        .overflow_hidden()
}
pub fn label(text: impl Into<SharedString>, font: f32, color: Hsla) -> Div {
    div()
        .text_size(px(font))
        .line_height(px(font * 1.42))
        .text_color(color)
        .child(text.into())
}
pub fn button(id: impl Into<ElementId>, name: impl Into<SharedString>, cx: &App) -> Stateful<Div> {
    let p = Paint::get(cx);
    let name = name.into();
    let debug = name.clone();
